def sections(m):
 slug,title,obj,deliver,limits,excluded,steps,accept,deps=m
 return [
 ('Objetivo',obj),
 ('Contexto do cliente','Situação atual: [DESCREVER]. Problema prioritário: [DESCREVER]. Resultado esperado e forma de avaliação: [DEFINIR].'),
 ('Entregas incluídas','\n'.join(f'{i+1}. {x}' for i,x in enumerate(deliver))),
 ('Limites do escopo',limits),('Itens não incluídos',excluded),
 ('Etapas e prazo',steps+'\nPrazo total: [PRAZO]. Início condicionado ao aceite, ao pagamento inicial previsto e às informações necessárias. Dependências pendentes serão comunicadas com impacto no cronograma.'),
 ('Responsabilidades e dependências',deps+'\nResponsável do cliente: [NOME]. Responsável pela execução: João Victor Vasconcelos. Acompanhamento: [CANAL E FREQUÊNCIA].'),
 ('Validação e aceite',accept+'\nPrazo para validação: [NÚMERO] dias úteis após a entrega. O cliente envia aceite ou divergências objetivas em relação ao escopo. Divergências serão corrigidas e novamente submetidas à validação. Ausência de resposta exige contato e replanejamento, sem aceite automático.'),
 ('Investimento e pagamento','Valor total do serviço: R$ [VALOR].\nForma de contratação: [PREÇO FECHADO OU HORAS COM LIMITE].\nEntrada: R$ [VALOR] em [DATA OU MARCO].\nDemais parcelas: [VALORES, VENCIMENTOS E MARCOS].\nTributos e despesas: [INCLUÍDOS OU DISCRIMINADOS].\nCustos de terceiros: [ITENS, ESTIMATIVAS, DATA DA COTAÇÃO E PAGADOR OU NÃO APLICÁVEL].\nRecorrência: [VALOR, ITENS, INÍCIO E VENCIMENTO OU NÃO CONTRATADA].'),
 ('Alterações e atendimento após a entrega','Solicitações fora do escopo serão avaliadas com impacto em preço e prazo e executadas após aprovação por escrito. Ajustes para cumprir o escopo aprovado não constituem novas funcionalidades.\nCorreções ou esclarecimentos incluídos: [PRAZO, QUANTIDADE E LIMITES]. Suporte continuado: [COBERTURA, CANAL, PRIMEIRA RESPOSTA, FRANQUIA E PREÇO OU NÃO CONTRATADO]. Tempo de resposta não equivale a prazo de solução.'),
 ('Entrega de materiais e encerramento','Materiais, arquivos, código, contas ou documentos entregues: [LISTA E FORMATO]. Condições de titularidade e licença: [DEFINIR]. Informações e acessos serão restritos às pessoas envolvidas na execução autorizada. Retenção, devolução e descarte: [DEFINIR]. Condições de suspensão, cancelamento e pagamento de entregas parciais: [ACORDAR].'),
 ('Aprovação','O aceite deve identificar esta proposta e sua versão, incluindo escopo, investimento, prazo e condições preenchidas.\nCliente: [RAZÃO SOCIAL OU NOME] • [CNPJ/CPF]\nRepresentante: [NOME E CARGO]\nAceite e data: [ASSINATURA OU REGISTRO ELETRÔNICO]\nProponente: João Victor Vasconcelos • [CNPJ/CPF]\nAceite e data: [ASSINATURA OU REGISTRO ELETRÔNICO]'),
 ]

articles=[]
for i,m in enumerate(models):
 slug,title,*_=m
 intro='João Victor Vasconcelos\n[E-MAIL] • [TELEFONE] • [SITE OU PORTFÓLIO]\nCliente: [CLIENTE] • Projeto: [PROJETO]\nProposta: [NÚMERO] • Versão: [VERSÃO]\nEmissão: [DATA] • Validade: [DATA]'
 pairs=sections(m)
 content=f'<div class="brand">JOÃO VICTOR VASCONCELOS</div><h1>Proposta de {escape(title.lower())}</h1><p class="meta">{escape(intro)}</p>'
 for n,(h,t) in enumerate(pairs,1): content+=f'<section><h2>{n:02d} {escape(h)}</h2><p>{escape(t)}</p></section>'
 articles.append(f'<article data-model="{slug}" contenteditable="true" spellcheck="true"'+(' hidden' if i else '')+'>'+content+'</article>')
 md=f'# Proposta de {title.lower()}\n\n{intro}\n\n'+'\n\n'.join(f'## {n:02d} {h}\n\n{t}' for n,(h,t) in enumerate(pairs,1))+'\n'
 (OUT/f'{i:02d}_{slug}.md').write_text(md,encoding='utf-8')

css='''*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#202d3a;font-family:Arial,sans-serif}header{background:#132e49;color:white;padding:24px 5vw}header h1{font-size:23px;margin:0 0 7px}header p{margin:0;color:#cbd7e3;font-size:14px}.tools{position:sticky;top:0;display:flex;flex-wrap:wrap;gap:9px;padding:14px 5vw;background:white;border-bottom:1px solid #d8e0e8;z-index:1}button,select{font:14px Arial;padding:11px 13px;border:1px solid #c3cfdb;border-radius:6px;background:white;color:#173957;cursor:pointer}button.primary{background:#176a8e;color:white;border-color:#176a8e}.hint{max-width:850px;margin:20px auto;padding:0 18px;font-size:14px;line-height:1.6}article{max-width:850px;margin:20px auto 45px;background:white;padding:55px 65px;box-shadow:0 5px 30px #16355112;outline:none}article[hidden]{display:none}.brand{font-size:12px;letter-spacing:2px;color:#176a8e;font-weight:bold}article h1{font-size:32px;line-height:1.15;color:#142e48;margin:20px 0}article h2{font-size:17px;color:#153d60;margin:27px 0 10px;break-after:avoid}article p{font-size:15px;line-height:1.65;white-space:pre-line;margin:0 0 14px}.meta{color:#576a7d;font-size:13px}section{margin:0}.sources{max-width:850px;margin:20px auto;padding:18px;font-size:13px;line-height:1.6}.status{width:100%;font-size:12px;color:#496477}@media(max-width:600px){article{padding:28px 22px;margin:12px}article h1{font-size:27px}.tools{position:static}header{padding:22px}}@media print{@page{size:A4;margin:18mm}body{background:white}header,.tools,.hint,.sources{display:none!important}article{box-shadow:none;max-width:none;margin:0;padding:0}article p{font-size:10pt;line-height:1.45}article h1{font-size:25pt}article h2{font-size:13pt}p{orphans:3;widows:3}}'''
js='''const picker=document.querySelector('select');const articles=[...document.querySelectorAll('article')];const status=document.getElementById('status');function current(){return articles.find(x=>!x.hidden)}function show(id){articles.forEach(x=>x.hidden=x.dataset.model!==id);document.body.dataset.active=id;picker.value=id;status.textContent='Modelo selecionado. Clique no texto para editar. Salve uma cópia para guardar as alterações.'}show(document.body.dataset.active||'geral');picker.addEventListener('change',()=>show(picker.value));document.addEventListener('input',e=>{if(e.target.closest('article'))status.textContent='Há alterações nesta sessão. Use Salvar kit editável antes de fechar.'});function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}document.getElementById('save').onclick=()=>{download('Propostas_Joao_Victor_editadas.html','<!doctype html>\\n'+document.documentElement.outerHTML,'text/html;charset=utf-8');status.textContent='Cópia solicitada ao navegador. Abra o arquivo baixado para continuar em outro dispositivo.'};document.getElementById('text').onclick=()=>{download('Proposta_'+current().dataset.model+'.txt',current().innerText,'text/plain;charset=utf-8')};document.getElementById('client').onclick=()=>{const copy=current().cloneNode(true);copy.removeAttribute('contenteditable');copy.removeAttribute('spellcheck');const html='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Proposta comercial</title><style>'+document.querySelector('style').textContent+'</style><body>'+copy.outerHTML+'</body></html>';download('Proposta_'+current().dataset.model+'.html',html,'text/html;charset=utf-8')};document.getElementById('print').onclick=()=>window.print();'''
opts=''.join(f'<option value="{m[0]}">{m[1]}</option>' for m in models)
html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Propostas de João Victor Vasconcelos</title><style>'+css+'</style></head><body data-active="geral"><header><h1>Suas propostas de tecnologia</h1><p>João Victor Vasconcelos • 7 modelos editáveis</p></header><div class="tools"><select aria-label="Modelo de proposta">'+opts+'</select><button class="primary" id="save">Salvar kit editável</button><button id="client">Baixar proposta para cliente</button><button id="text">Baixar texto</button><button id="print">Imprimir / PDF</button><div id="status" class="status" aria-live="polite"></div></div><div class="hint"><strong>Como usar:</strong> escolha o serviço e clique diretamente no texto. Substitua os campos [ENTRE COLCHETES], remova itens que não se aplicam e confira valores e condições. As mudanças ficam nesta sessão até você salvar o kit. Não há sincronização automática entre dispositivos.</div>'+''.join(articles)+'<aside class="sources"><strong>Referências e instruções internas — não entram na impressão</strong><p>Estrutura comercial pesquisada em <a href="https://www.pandadoc.com/software-development-sow-template/">PandaDoc</a> e <a href="https://www.proposalkit.com/htm/business-proposal-example/sample-business-proposal/sample-software-automation-consulting-proposal.htm">Proposal Kit</a>. Para consultoria: <a href="https://www.pandadoc.com/blog/how-to-write-a-consulting-proposal/">PandaDoc Consulting</a>. Para o processo técnico de perícia: <a href="https://csrc.nist.gov/pubs/sp/800/86/final">NIST SP 800-86</a>. Consulta em 25/09/2026. Textos originais adaptados aos serviços informados.</p><p>Antes do envio, confira todos os campos, escopo, somas, prazos, identificação e condições comerciais. Para compartilhar somente a proposta escolhida, use Baixar proposta para cliente ou Imprimir / PDF. Guarde o kit completo para reutilização.</p></aside><script>'+js+'</script></body></html>'
(OUT/'Editor_de_Propostas.html').write_text(html,encoding='utf-8')
(OUT/'LEIA-ME.txt').write_text('KIT DE PROPOSTAS — JOÃO VICTOR VASCONCELOS\n\nAbra Editor_de_Propostas.html no navegador. Escolha um dos 7 modelos e clique no texto para editar. Salvar kit editável baixa uma cópia com as alterações de todos os modelos. Mova essa cópia para continuar em outro dispositivo. Não há sincronização automática.\n\nBaixar proposta para cliente exporta somente o modelo atual, sem as instruções. Imprimir / PDF usa a função do navegador. Baixar texto permite copiar para Word, Google Docs ou outro editor. Os 7 arquivos .md também podem ser abertos como texto.\n\nEm celulares que abrem HTML apenas em pré-visualização, use o navegador com suporte a arquivos locais ou os arquivos .md em um editor de texto.\n\nPreencha todos os campos entre colchetes, confira os valores e remova itens não aplicáveis antes de enviar. Preços, qualificações profissionais e resultados anteriores não foram inventados.\n',encoding='utf-8')
with zipfile.ZipFile(OUT/'Kit_Propostas_Joao_Victor.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in OUT.iterdir():
  if f.suffix in ['.html','.md','.txt']:z.write(f,f.name)
print(OUT)
